new:
let device_identity = Arc::as_ptr(&render_state.device) as usize;
if self.renderer_device != Some(device_identity) {
    self.renderer = None;
    #[cfg(not(target_arch = "wasm32"))]
    {
        self.renderer_warmup = None;
    }
    self.residency.clear_gpu();
    self.renderer_device = Some(device_identity);
}

#[cfg(not(target_arch = "wasm32"))]
if self.renderer.is_none() {
    let mut warmup_failed = None;
    if let Some(warmup) = &self.renderer_warmup {
        match warmup.receiver.try_recv() {
            Ok(Ok(renderer)) => self.renderer = Some(renderer),
            Ok(Err(message)) => warmup_failed = Some(message),
            Err(std::sync::mpsc::TryRecvError::Empty) => {}
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                warmup_failed = Some("preview renderer warm-up worker disconnected".into());
            }
        }
    }
    if self.renderer.is_some() || warmup_failed.is_some() {
        self.renderer_warmup = None;
    }
    if let Some(message) = warmup_failed {
        self.preview_notice = Some(PreviewNotice::failure(
            "editor.scene_view.renderer_failed",
            format!("Scene View renderer failed: {message}"),
        ));
    } else if self.renderer.is_none() && self.renderer_warmup.is_none() {
        let device = Arc::clone(&render_state.device);
        let queue = Arc::clone(&render_state.queue);
        let texture_cache = self.residency.gpu_texture_cache();
        let (sender, receiver) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let result = pollster::block_on(engine::PreviewRenderer::new_with_shared_textures(
                &device,
                &queue,
                PREVIEW_RENDER_FORMAT,
                texture_cache,
            ))
            .map_err(|error| error.to_string());
            let _ = sender.send(result);
        });
        self.renderer_warmup = Some(PreviewRendererWarmup { receiver });
    }
    if self.renderer.is_none() {
        response
            .ctx
            .request_repaint_after(std::time::Duration::from_millis(16));
        ui.painter().text(
            rect.center(),
            egui::Align2::CENTER_CENTER,
            "Preparing preview renderer...",
            egui::FontId::proportional(14.0),
            egui::Color32::WHITE,
        );
    }
}

